// What the Worker is given: the bindings in wrangler.toml (Env, generated by
// `npm run types` into worker-configuration.d.ts), and the vars and secrets
// set with npm run config. Most settings arrive as JSON text from wrangler;
// settings.ts may replace some with parsed values, so those are loose here.
export interface AppEnv extends Env {
  SLACK_BOT_TOKEN: string;
  SLACK_SIGNING_SECRET: string;
  PUBLIC_URL?: string;
  TIMEZONE?: string;
  ADMINS?: string | string[];
  PROJECTS?: unknown;
  PROJECTS_BASE?: unknown;
  AI_MODEL_NAME?: string;
  MCP?: string;
  SUMMARY_SETTLE_MS?: string | number;
  TASK_CHANGE_DETECTION?: string;
  // Features for every project, "on" or "off" (see groupEnabled in channels.ts).
  NEW_TASK_DETECTION?: string;
  AI_AGENT_SUMMARY?: string;
  SUMMARY_CANVAS?: string;
}

export type FeatureSecret = "NEW_TASK_DETECTION" | "AI_AGENT_SUMMARY" | "SUMMARY_CANVAS";
